-- Align catalogue labels with the manuscript and decks supplied on 2026-11-03.
-- Metadata only: no result rows, fitted estimates, source hashes or publication flags change.
begin;
do $check$
declare updates jsonb := $mapping$[{"id": "manuscript/asah1_labels", "old_title": "Figure S19b · ASAH1 glycofeature identities", "old_description": "A01–A20 identify distinct peptide-plus-glycan features. All 20 conditional estimates are retained.", "title": "Figure S15b · ASAH1 glycofeature identities", "description": "A01–A20 identify distinct peptide-plus-glycan features. All 20 conditional estimates are retained."}, {"id": "manuscript/candidate_sensitivity_coverage", "old_title": "Figure S18 · candidate sensitivity coverage", "old_description": "Covariate-sensitivity availability for 27 of 81 primary conditional candidates: 24 selected features plus three ASAH1 glycoforms.", "title": "Figure S14b · candidate sensitivity coverage", "description": "Covariate-sensitivity availability for 27 of 81 primary conditional candidates: 24 selected features plus three ASAH1 glycoforms."}, {"id": "manuscript/ptm_calibration_summary", "old_title": "Figure S24 · PTM calibration summary", "old_description": "Six quantities, five scenarios and two scopes: all completed versus numerically adequate fits. Coverage bars are Wilson confidence intervals, not HDIs. No screen-wide false-discovery control.", "title": "Figures S18–S20 · PTM calibration summary", "description": "Six quantities, five scenarios and two scopes: all completed versus numerically adequate fits. Figure S18 shows coverage, S19 bias and S20 RMSE. Coverage bars are Wilson confidence intervals, not HDIs. No screen-wide false-discovery control."}, {"id": "manuscript/ptm_calibration_templates", "old_title": "Figure S24 · calibration by template", "old_description": "Separate phospho and glyco template results; aggregate summaries across simulated replicates.", "title": "Figures S18–S20 · calibration by template", "description": "Separate phospho and glyco template results; aggregate summaries across simulated replicates."}, {"id": "manuscript/ptm_calibration_replicates", "old_title": "Figure S24 · per-replicate calibration metrics", "old_description": "250 simulated datasets × six quantities. Literal null denotes the null scenario; these are simulated quantities, not patient records.", "title": "Figures S18–S20 · per-replicate calibration metrics", "description": "250 simulated datasets × six quantities. Literal null denotes the null scenario; these are simulated quantities, not patient records."}, {"id": "manuscript/ptm_calibration_completion", "old_title": "Figure S24e · calibration sample counts", "old_description": "250 completed simulated datasets; 249 numerically adequate.", "title": "Figure S21b · calibration sample counts", "description": "250 completed simulated datasets; 249 numerically adequate."}, {"id": "manuscript/ptm_sbc_bins", "old_title": "Figure S24d · SBC rank histogram counts", "old_description": "Pointwise 95% binomial reference limits are not simultaneous bands or a formal calibration test.", "title": "Figure S21a · SBC rank histogram counts", "description": "Pointwise 95% binomial reference limits are not simultaneous bands or a formal calibration test."}, {"id": "manuscript/ptm_sbc_values", "old_title": "Figure S24d · SBC ranks", "old_description": "Prior-predictive SBC ranks for 50 simulated datasets × six quantities. Randomized ties use seed 20261004.", "title": "Figure S21a · SBC ranks", "description": "Prior-predictive SBC ranks for 50 simulated datasets × six quantities. Randomized ties use seed 20261004."}, {"id": "manuscript/sensitivity_feature_labels", "old_title": "Figure S25 · sensitivity feature identities", "old_description": "E01–E24 map to the 24 post hoc selected features from CTSD, HLA-DRA, LAMC1, POSTN and GSDMD.", "title": "Figures S22–S24 · sensitivity feature identities", "description": "E01–E24 map to the 24 post hoc selected features from CTSD, HLA-DRA, LAMC1, POSTN and GSDMD."}, {"id": "manuscript/sensitivity_comparisons", "old_title": "Figure S25 · matched sensitivity comparisons", "old_description": "192 comparisons. Stage and purity adjustment use the matched unadjusted subset; restriction and other variants use the primary fit. Classification changes are descriptive, not posterior contrast tests.", "title": "Figures S23–S24 · matched sensitivity comparisons", "description": "192 comparisons. Figure S23: fixed plex, stage subset, stage adjustment and purity subset. Figure S24: purity adjustment, mutation adjustment, weight-loss exclusion and adenosquamous exclusion. Stage and purity adjustment use the matched unadjusted subset; restriction and other variants use the primary fit. Classification changes are descriptive, not posterior contrast tests."}, {"id": "manuscript/sensitivity_classifications", "old_title": "Figure S25b · interval classifications", "old_description": "Counts retained or changed in each comparison among 24 post hoc features. Both compared fits must be numerically adequate.", "title": "Figure S22b · interval classifications", "description": "Counts retained or changed in each comparison among 24 post hoc features. Both compared fits must be numerically adequate."}, {"id": "ptm/extended_sensitivity_effects", "old_title": "Figure S25 · expanded PTM sensitivity estimates", "old_description": "24 post hoc selected features, primary references and eight sensitivity variants. 192 refits; all numerically adequate. Use matched subsets for stage and purity adjustment.", "title": "Figures S22–S24 · expanded PTM sensitivity estimates", "description": "24 post hoc selected features, primary references and eight sensitivity variants. 192 refits; all numerically adequate. Figure S22a shows the overview; Figures S23–S24 show variant-specific comparisons. Use matched subsets for stage and purity adjustment."}, {"id": "manuscript/rna_heatmap_values", "old_title": "Figure 3 · RNA heatmap values", "old_description": "Displayed continuous RNA coefficients for the 24 selected signature rows. Unmodeled combinations remain missing.", "title": "Figure 3a · RNA heatmap values", "description": "Displayed continuous RNA coefficients for the 24 selected signature rows. Unmodeled combinations remain missing. The named examples in Figures 3b–e are available in the compartment RNA effects collections."}, {"id": "manuscript/ptm_heatmap_lookup", "old_title": "Figure 6 · PTM heatmap identities and estimates", "old_description": "All 14 phospho and top 20 of 67 glyco conditional candidates. Gene, site/peptide/glycan, both effects and pointwise HDIs; magnitude-ranked without multiplicity control.", "title": "Figures 6c,d · PTM heatmap identities and estimates", "description": "All 14 phospho and top 20 of 67 glyco conditional candidates. Gene, site/peptide/glycan, both effects and pointwise HDIs; magnitude-ranked without multiplicity control."}]$mapping$::jsonb;
begin
 if exists (
   select 1 from jsonb_to_recordset(updates) as u(id text, old_title text, old_description text, title text, description text)
   left join public.atlas_web_datasets d on d.id=u.id
   where d.id is null or d.run_key <> 'manuscript_ptm_20261004'
      or d.title not in (u.old_title,u.title)
      or d.description not in (u.old_description,u.description)
 ) then raise exception 'Manuscript catalogue changed or required collections are missing; review before updating'; end if;
 update public.atlas_web_datasets d set title=u.title, description=u.description
 from jsonb_to_recordset(updates) as u(id text, title text, description text)
 where d.id=u.id and (d.title,d.description) is distinct from (u.title,u.description);
end $check$;
update public.atlas_figure_specs set title='Figures S18–S20 · PTM calibration',
 parameters=parameters || '{"figure_references":{"calibration_coverage":"S18","calibration_bias":"S19","calibration_rmse":"S20"}}'::jsonb
 where figure_key='manuscript/PTM_calibration';
update public.atlas_figure_specs set title='Figures 6c,d · supported PTM BMI effects',
 parameters=parameters || '{"figure_references":{"phospho":"6c","glyco":"6d"}}'::jsonb
 where figure_key='manuscript/PTM_primary';
update public.atlas_figure_specs set title='Figure S22a · expanded PTM sensitivities',
 parameters=parameters || '{"figure_references":{"sensitivity_grid":"S22a"}}'::jsonb
 where figure_key='manuscript/PTM_sensitivity';
commit;
